// Package store owns all SQL that is not compiled from a segment rule, and
// the migration runner.
package store

import (
	"context"
	"database/sql"
	"fmt"
	"log/slog"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"
	"github.com/riverqueue/river/riverdriver/riverpgxv5"
	"github.com/riverqueue/river/rivermigrate"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/migrations"
)

// riverLock serializes River migrations across concurrent runs, like the
// goose session lock does for the app migrations.
const riverLock int64 = 0x717e7

// newMigrator builds a goose provider over the embedded migrations. A
// Postgres advisory lock makes concurrent runs (compose setup, tests) wait
// for each other instead of racing.
func newMigrator(db *sql.DB) (*goose.Provider, error) {
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return nil, err
	}
	return goose.NewProvider(goose.DialectPostgres, db, migrations.FS, goose.WithSessionLocker(locker))
}

// newRiverMigrator builds a River migrator. The driver has no pool, so only
// the Tx variants work; callers pass a transaction on db's connection.
func newRiverMigrator() (*rivermigrate.Migrator[pgx.Tx], error) {
	return rivermigrate.New(riverpgxv5.New(nil), &rivermigrate.Config{Logger: slog.New(slog.DiscardHandler)})
}

// inTx runs fn in a transaction on one pgx connection taken from db, and
// commits if fn succeeds.
func inTx(ctx context.Context, db *sql.DB, opts pgx.TxOptions, fn func(pgx.Tx) error) error {
	conn, err := db.Conn(ctx)
	if err != nil {
		return err
	}
	defer conn.Close()
	return conn.Raw(func(dc any) error {
		tx, err := dc.(*stdlib.Conn).Conn().BeginTx(ctx, opts)
		if err != nil {
			return err
		}
		defer tx.Rollback(ctx)
		if err := fn(tx); err != nil {
			return err
		}
		return tx.Commit(ctx)
	})
}

// Migrate applies every pending migration: the app's (goose), then River's
// queue tables (rivermigrate). It does not close db.
func Migrate(ctx context.Context, db *sql.DB) error {
	p, err := newMigrator(db)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	if _, err := p.Up(ctx); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	rm, err := newRiverMigrator()
	if err != nil {
		return fmt.Errorf("migrate river: %w", err)
	}
	err = inTx(ctx, db, pgx.TxOptions{}, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, "SELECT pg_advisory_xact_lock($1)", riverLock); err != nil {
			return err
		}
		_, err := rm.MigrateTx(ctx, tx, rivermigrate.DirectionUp, nil)
		return err
	})
	if err != nil {
		return fmt.Errorf("migrate river: %w", err)
	}
	return nil
}

// Pending reports whether db lacks any embedded migration or any River
// migration (for /readyz). It only reads, so it takes no lock.
func Pending(ctx context.Context, db *sql.DB) (bool, error) {
	p, err := goose.NewProvider(goose.DialectPostgres, db, migrations.FS)
	if err != nil {
		return false, err
	}
	pending, err := p.HasPending(ctx)
	if err != nil || pending {
		return pending, err
	}
	rm, err := newRiverMigrator()
	if err != nil {
		return false, err
	}
	var ok bool
	err = inTx(ctx, db, pgx.TxOptions{AccessMode: pgx.ReadOnly}, func(tx pgx.Tx) error {
		res, err := rm.ValidateTx(ctx, tx, nil)
		if err != nil {
			return err
		}
		ok = res.OK
		return nil
	})
	return !ok, err
}
package store

import (
	"context"
	"database/sql"
	"testing"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// The tables rivermigrate creates. Jobs cannot be inserted without them.
var riverTables = []string{"river_job", "river_leader", "river_queue", "river_migration"}

func missingRiverTables(t *testing.T, db *sql.DB) []string {
	t.Helper()
	var missing []string
	for _, tbl := range riverTables {
		var ok bool
		if err := db.QueryRow("SELECT to_regclass('public.' || $1) IS NOT NULL", tbl).Scan(&ok); err != nil {
			t.Fatal(err)
		}
		if !ok {
			missing = append(missing, tbl)
		}
	}
	return missing
}

// TestMigrateRunsRiver checks that Migrate creates the River tables after
// the goose migrations, and that a second run is a no-op.
func TestMigrateRunsRiver(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)
	if err := Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	if missing := missingRiverTables(t, db); len(missing) != 0 {
		t.Fatalf("after Migrate: River tables missing: %v", missing)
	}
	if pending, err := Pending(ctx, db); err != nil || pending {
		t.Fatalf("after Migrate: Pending = %v, %v; want false", pending, err)
	}
	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("second run is not a no-op: %v", err)
	}
}

// TestPendingCoversRiver applies only the goose migrations. The database
// then has every app table but no River tables, so it is not ready: /readyz
// must not report ok for a database the worker cannot use.
func TestPendingCoversRiver(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)
	p, err := newMigrator(db)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := p.Up(ctx); err != nil {
		t.Fatal(err)
	}
	if missing := missingRiverTables(t, db); len(missing) != len(riverTables) {
		t.Fatalf("goose alone created River tables; this test no longer isolates them (missing %v)", missing)
	}
	if pending, err := Pending(ctx, db); err != nil || !pending {
		t.Fatalf("goose done, River missing: Pending = %v, %v; want true", pending, err)
	}
	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("Migrate on a goose-only database: %v", err)
	}
	if pending, err := Pending(ctx, db); err != nil || pending {
		t.Fatalf("after Migrate: Pending = %v, %v; want false", pending, err)
	}
}

// TestTemplateHasRiver checks the template that make test builds, so every
// integration package gets River tables in its clone.
func TestTemplateHasRiver(t *testing.T) {
	url, _ := testdb.Seeded(t)
	db, err := sql.Open("pgx", url)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if missing := missingRiverTables(t, db); len(missing) != 0 {
		t.Fatalf("template clone lacks River tables: %v", missing)
	}
	if pending, err := Pending(context.Background(), db); err != nil || pending {
		t.Fatalf("template clone: Pending = %v, %v; want false", pending, err)
	}
}
// Package testdb gives integration tests their own Postgres database, so
// packages can run in parallel without touching each other's data.
//
// Tests need TEST_DATABASE_URL (an admin connection to the test server).
// Without it they skip, unless REQUIRE_DB=1, which make test sets: then a
// missing database fails the run instead of silently skipping it.
package testdb

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"net/url"
	"os"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
)

// cloneLock serializes template clones across test packages: Postgres
// refuses to copy a template database while another session uses it.
const cloneLock int64 = 0x7e57db

// Fresh creates an empty database for the calling test, drops it when the
// test ends, and returns its connection URL.
func Fresh(t testing.TB) string {
	t.Helper()
	return create(t, "")
}

// Seed describes the data in a seeded clone, read from its seed_meta row.
type Seed struct {
	AsOf  time.Time
	Seed  int64
	Users int
}

// Seeded clones the template database that make test builds (migrated, then
// seeded at a fixed anchor) for the calling test, drops the clone when the
// test ends, and returns its URL and seed parameters. The template name is
// TEST_TEMPLATE_DB, default app_template.
func Seeded(t testing.TB) (string, Seed) {
	t.Helper()
	template := os.Getenv("TEST_TEMPLATE_DB")
	if template == "" {
		template = "app_template"
	}
	u := create(t, template)

	db, err := sql.Open("pgx", u)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var s Seed
	if err := db.QueryRow("SELECT as_of, seed, user_count FROM seed_meta").Scan(&s.AsOf, &s.Seed, &s.Users); err != nil {
		t.Fatalf("template %s has no seed_meta row (build it with make test): %v", template, err)
	}
	s.AsOf = s.AsOf.UTC()
	return u, s
}

func create(t testing.TB, template string) string {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		if os.Getenv("REQUIRE_DB") == "1" {
			t.Fatal("REQUIRE_DB=1 but TEST_DATABASE_URL is not set")
		}
		t.Skip("TEST_DATABASE_URL is not set; run the integration tests with make test")
	}
	admin, err := sql.Open("pgx", base)
	if err != nil {
		t.Fatal(err)
	}
	b := make([]byte, 6)
	_, _ = rand.Read(b)
	name := "test_" + hex.EncodeToString(b)

	ctx := context.Background()
	conn, err := admin.Conn(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stmt := "CREATE DATABASE " + name
	if template != "" {
		stmt += " TEMPLATE " + pgx.Identifier{template}.Sanitize()
		if _, err := conn.ExecContext(ctx, "SELECT pg_advisory_lock($1)", cloneLock); err != nil {
			t.Fatal(err)
		}
	}
	_, createErr := conn.ExecContext(ctx, stmt)
	if template != "" {
		_, _ = conn.ExecContext(ctx, "SELECT pg_advisory_unlock($1)", cloneLock)
	}
	conn.Close()
	if createErr != nil {
		t.Fatalf("%s: %v (the template is built by make test)", stmt, createErr)
	}

	t.Cleanup(func() {
		if _, err := admin.Exec("DROP DATABASE " + name + " WITH (FORCE)"); err != nil {
			t.Errorf("drop %s: %v", name, err)
		}
		admin.Close()
	})
	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	u.Path = "/" + name
	return u.String()
}

package httpapi

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"regexp"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// HTTP-level error codes, next to the validation codes.
const (
	codeUnauthorized = "unauthorized"
	codeBodyTooLarge = "body_too_large"
	codeInternal     = "internal"
)

const (
	maxBody      = 64 << 10
	queryTimeout = 3 * time.Second
)

// Server holds the API's dependencies.
type Server struct {
	Config  Config
	Pool    *pgxpool.Pool
	Schemas *schema.Set
	Log     *slog.Logger
	Now     func() time.Time // defaults to time.Now; tests pin it
}

// Handler builds the routes. It refuses to build an open API: with no token,
// ALLOW_UNAUTHENTICATED must have been set explicitly.
func (s *Server) Handler() (http.Handler, error) {
	if s.Config.AdminToken == "" && !s.Config.AllowUnauthenticated {
		return nil, ErrNoToken
	}
	if s.Now == nil {
		s.Now = time.Now
	}
	if s.Log == nil {
		s.Log = slog.New(slog.DiscardHandler)
	}
	api := http.NewServeMux()
	api.HandleFunc("POST /api/audience/count", s.count)
	s.campaignRoutes(api)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", s.healthz)
	mux.HandleFunc("GET /readyz", s.readyz)
	// Everything under /api is behind auth, unknown paths included, so an
	// unauthenticated caller cannot map the routes.
	mux.Handle("/api/", s.auth(api))
	return s.requestID(s.logRequests(mux)), nil
}

type ctxKey struct{}

var requestIDPattern = regexp.MustCompile(`^[A-Za-z0-9-]{1,64}$`)

// requestID keeps a well-formed X-Request-ID and replaces anything else, so
// a caller cannot inject log lines or huge values.
func (s *Server) requestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-ID")
		if !requestIDPattern.MatchString(id) {
			b := make([]byte, 8)
			_, _ = rand.Read(b)
			id = hex.EncodeToString(b)
		}
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, id)))
	})
}

func requestIDFrom(ctx context.Context) string {
	id, _ := ctx.Value(ctxKey{}).(string)
	return id
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

// logRequests logs method, path, status and duration. Never bodies, query
// strings or headers.
func (s *Server) logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		sw := &statusWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(sw, r)
		s.Log.Info("request", "method", r.Method, "path", r.URL.Path, "status", sw.status,
			"duration_ms", time.Since(start).Milliseconds(), "request_id", requestIDFrom(r.Context()))
	})
}

// auth checks the bearer token. Both sides are hashed first, so the
// constant-time compare also hides the token's length.
func (s *Server) auth(next http.Handler) http.Handler {
	if s.Config.AdminToken == "" {
		return next // only reachable with AllowUnauthenticated; Handler checks
	}
	want := sha256.Sum256([]byte(s.Config.AdminToken))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		got := sha256.Sum256([]byte(token))
		if !ok || subtle.ConstantTimeCompare(got[:], want[:]) != 1 {
			w.Header().Set("WWW-Authenticate", `Bearer realm="api"`)
			writeError(w, http.StatusUnauthorized, codeUnauthorized, "missing or invalid bearer token")
			return
		}
		next.ServeHTTP(w, r)
	})
}

func (s *Server) healthz(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

// readyz checks the database is reachable and fully migrated. Liveness
// (healthz) deliberately checks nothing outside the process.
func (s *Server) readyz(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
	defer cancel()
	notReady := func(reason string) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "unavailable", "reason": reason})
	}
	if err := s.Pool.Ping(ctx); err != nil {
		notReady("database unreachable")
		return
	}
	db := stdlib.OpenDBFromPool(s.Pool) // goose needs database/sql; closing it leaves the pool open
	defer db.Close()
	if pending, err := store.Pending(ctx, db); err != nil || pending {
		notReady("migrations pending")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

type countResponse struct {
	segment.Counts
	AsOf     time.Time  `json:"as_of"`
	SeededAt *time.Time `json:"seeded_at"`
}

// count validates a segment rule and returns its audience size.
func (s *Server) count(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	doc, err := schema.Decode(r.Body)
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, codeBodyTooLarge, "body is larger than 64 KiB")
			return
		}
		writeError(w, http.StatusBadRequest, validation.InvalidJSON, err.Error())
		return
	}

	var res validation.Result
	body, isObject := doc.(map[string]any)
	switch {
	case !isObject:
		res.Error("", validation.InvalidType, `expected an object: {"rule": {...}}`)
	default:
		for k := range body {
			if k != "rule" {
				res.Error("/"+k, validation.UnknownProperty, `only "rule" is allowed`)
			}
		}
		if _, ok := body["rule"]; !ok {
			res.Error("/rule", validation.Required, `missing required key "rule"`)
		}
	}
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	rule, res := segment.Validate(s.Schemas, body["rule"])
	if !res.OK() {
		for i := range res.Errors {
			res.Errors[i].Path = "/rule" + res.Errors[i].Path
		}
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	asOf := s.Now().UTC().Truncate(time.Microsecond)
	counts, err := segment.CountAudience(ctx, s.Pool, rule, asOf)
	if err != nil {
		s.Log.Error("count failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "counting the audience failed")
		return
	}
	seededAt, err := store.SeededAt(ctx, s.Pool)
	if err != nil {
		s.Log.Error("reading seed_meta failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "counting the audience failed")
		return
	}
	writeJSON(w, http.StatusOK, countResponse{Counts: counts, AsOf: asOf, SeededAt: seededAt})
}

type errorBody struct {
	Errors []validation.Issue `json:"errors"`
}

func issues(list []validation.Issue) errorBody { return errorBody{Errors: list} }

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, issues([]validation.Issue{{Path: "", Code: code, Message: message}}))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
