package llm

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"reflect"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/retry"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// fakeAPI records every request and answers with handle. These tests use
// their own tiny server rather than internal/mockllm, so the client's
// contract is pinned independently of the mock.
type fakeAPI struct {
	mu      sync.Mutex
	bodies  []map[string]any
	headers []http.Header
	paths   []string
}

func (a *fakeAPI) count() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return len(a.bodies)
}

func (a *fakeAPI) body(i int) map[string]any {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.bodies[i]
}

func newFakeAPI(t *testing.T, handle func(n int, w http.ResponseWriter, r *http.Request)) (*fakeAPI, *httptest.Server) {
	t.Helper()
	a := &fakeAPI{}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		var body map[string]any
		_ = json.Unmarshal(raw, &body)
		a.mu.Lock()
		n := len(a.bodies)
		a.bodies = append(a.bodies, body)
		a.headers = append(a.headers, r.Header.Clone())
		a.paths = append(a.paths, r.URL.Path)
		a.mu.Unlock()
		handle(n, w, r)
	}))
	t.Cleanup(srv.Close)
	return a, srv
}

func js(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func event(w http.ResponseWriter, name, data string) {
	fmt.Fprintf(w, "event: %s\ndata: %s\n\n", name, data)
	w.(http.Flusher).Flush()
}

// streamStart writes the events before the first text delta: message_start
// and an empty thinking block with a signature, as Opus 5.5 sends them.
func streamStart(w http.ResponseWriter, sig string) {
	w.Header().Set("Content-Type", "text/event-stream")
	w.WriteHeader(http.StatusOK)
	event(w, "message_start", `{"type":"message_start","message":{"id":"msg_test","type":"message","role":"assistant","model":"claude-opus-5-5","content":[],"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":42,"output_tokens":1}}}`)
	event(w, "content_block_start", `{"type":"content_block_start","index":0,"content_block":{"type":"thinking","thinking":"","signature":""}}`)
	event(w, "content_block_delta", `{"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":`+js(sig)+`}}`)
	event(w, "content_block_stop", `{"type":"content_block_stop","index":0}`)
	event(w, "content_block_start", `{"type":"content_block_start","index":1,"content_block":{"type":"text","text":""}}`)
}

func textDelta(w http.ResponseWriter, chunk string) {
	event(w, "content_block_delta", `{"type":"content_block_delta","index":1,"delta":{"type":"text_delta","text":`+js(chunk)+`}}`)
}

// writeStream writes a whole streamed answer.
func writeStream(w http.ResponseWriter, sig, stop string, chunks ...string) {
	streamStart(w, sig)
	for _, c := range chunks {
		textDelta(w, c)
	}
	event(w, "content_block_stop", `{"type":"content_block_stop","index":1}`)
	event(w, "message_delta", `{"type":"message_delta","delta":{"stop_reason":`+js(stop)+`,"stop_sequence":null},"usage":{"output_tokens":17}}`)
	event(w, "message_stop", `{"type":"message_stop"}`)
}

func apiError(w http.ResponseWriter, status int, typ, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	fmt.Fprintf(w, `{"type":"error","error":{"type":%s,"message":%s}}`, js(typ), js(msg))
}

func schemas(t *testing.T) *schema.Set {
	t.Helper()
	set, err := schema.Load()
	if err != nil {
		t.Fatal(err)
	}
	return set
}

func testClient(t *testing.T, baseURL string, mod func(*Config)) *Client {
	t.Helper()
	cfg := Config{BaseURL: baseURL, APIKey: "test-placeholder", Schemas: schemas(t), StallTimeout: 5 * time.Second, TotalTimeout: 10 * time.Second}
	if mod != nil {
		mod(&cfg)
	}
	c, err := New(cfg)
	if err != nil {
		t.Fatal(err)
	}
	return c
}

// systemText reads the system prompt, sent as a string or as text blocks.
func systemText(body map[string]any) string {
	switch s := body["system"].(type) {
	case string:
		return s
	case []any:
		var sb strings.Builder
		for _, b := range s {
			if m, ok := b.(map[string]any); ok {
				t, _ := m["text"].(string)
				sb.WriteString(t)
			}
		}
		return sb.String()
	}
	return ""
}

func messages(body map[string]any) []map[string]any {
	list, _ := body["messages"].([]any)
	var out []map[string]any
	for _, m := range list {
		mm, _ := m.(map[string]any)
		out = append(out, mm)
	}
	return out
}

// blocks reads a message's content as blocks; a plain string is one text block.
func blocks(m map[string]any) []map[string]any {
	switch c := m["content"].(type) {
	case string:
		return []map[string]any{{"type": "text", "text": c}}
	case []any:
		var out []map[string]any
		for _, b := range c {
			bm, _ := b.(map[string]any)
			out = append(out, bm)
		}
		return out
	}
	return nil
}

func messageText(m map[string]any) string {
	var sb strings.Builder
	for _, b := range blocks(m) {
		if b["type"] == "text" {
			s, _ := b["text"].(string)
			sb.WriteString(s)
		}
	}
	return sb.String()
}

// normalize round-trips a value through encoding/json, so two decoded
// schemas compare equal whatever number types they used.
func normalize(t *testing.T, v any) any {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	var out any
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

// TestRequestShape pins what goes over the wire for each stage: model,
// adaptive thinking, explicit effort, JSON outputs with the API-derived
// schema, streaming, the refusal fallback, and nothing the API rejects.
func TestRequestShape(t *testing.T) {
	set := schemas(t)
	cases := []struct {
		stage  Stage
		name   schema.Name
		effort string
	}{
		{Segment, schema.SegmentRule, "low"},
		{Content, schema.Content, "medium"},
	}
	for _, c := range cases {
		api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", "end_turn", `{}`) })
		cl := testClient(t, srv.URL, nil)
		if _, err := cl.Call(context.Background(), NewConversation(c.stage, "first turn"), nil); err != nil {
			t.Fatalf("%s: %v", c.stage, err)
		}
		if api.count() != 1 {
			t.Fatalf("%s: %d requests, want 1", c.stage, api.count())
		}
		body, h := api.body(0), api.headers[0]
		if !strings.HasPrefix(api.paths[0], "/v1/messages") {
			t.Errorf("%s: path %q", c.stage, api.paths[0])
		}
		if body["model"] != DefaultModel {
			t.Errorf("%s: model %v, want %s", c.stage, body["model"], DefaultModel)
		}
		if body["stream"] != true {
			t.Errorf("%s: stream = %v, want true", c.stage, body["stream"])
		}
		if mt, _ := body["max_tokens"].(float64); mt <= 0 {
			t.Errorf("%s: max_tokens %v", c.stage, body["max_tokens"])
		}
		if th, _ := body["thinking"].(map[string]any); th["type"] != "adaptive" {
			t.Errorf("%s: thinking %v, want adaptive (Opus 5.5 cannot disable it)", c.stage, body["thinking"])
		}
		oc, _ := body["output_config"].(map[string]any)
		if oc["effort"] != c.effort {
			t.Errorf("%s: effort %v, want %s set explicitly", c.stage, oc["effort"], c.effort)
		}
		format, _ := oc["format"].(map[string]any)
		if format["type"] != "json_schema" {
			t.Errorf("%s: output_config.format %v, want json_schema", c.stage, format)
		}
		want, err := set.ForAPI(c.name)
		if err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(normalize(t, format["schema"]), normalize(t, want)) {
			t.Errorf("%s: the schema sent is not schema.ForAPI(%s)", c.stage, c.name)
		}
		for _, banned := range []string{"temperature", "top_p", "top_k", "tools", "tool_choice"} {
			if _, ok := body[banned]; ok {
				t.Errorf("%s: request has %q", c.stage, banned)
			}
		}
		if body["fallbacks"] != "default" {
			t.Errorf("%s: fallbacks %v, want \"default\"", c.stage, body["fallbacks"])
		}
		if !strings.Contains(strings.Join(h.Values("anthropic-beta"), ","), FallbackBeta) {
			t.Errorf("%s: anthropic-beta %q lacks %s", c.stage, h.Values("anthropic-beta"), FallbackBeta)
		}
		if h.Get("x-api-key") != "test-placeholder" || h.Get("anthropic-version") == "" {
			t.Errorf("%s: auth headers %v", c.stage, h)
		}
		if got := systemText(body); !strings.Contains(got, SystemPrompt(c.stage)) {
			t.Errorf("%s: system prompt not sent", c.stage)
		}
		msgs := messages(body)
		if len(msgs) != 1 || msgs[0]["role"] != "user" || messageText(msgs[0]) != "first turn" {
			t.Errorf("%s: messages %v", c.stage, msgs)
		}
	}
}

