		_, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", stop, `{"sms":{"bo`) })
		resp, err := testClient(t, srv.URL, nil).Call(context.Background(), NewConversation(Content, "x"), nil)
