// SDK retries are off: every retry goes through internal/retry. A failing
// call is classified, and the API's error message is kept for llm_calls.
func TestErrorsAreClassifiedAndNotRetried(t *testing.T) {
	cases := []struct {
		name       string
		status     int
		typ, msg   string
		retryAfter string
		class      retry.Class
		after      time.Duration
	}{
		{"500", 500, "api_error", "internal", "", retry.ServerError, 0},
		{"529 overloaded", 529, "overloaded_error", "Overloaded", "", retry.ServerError, 0},
		{"429", 429, "rate_limit_error", "slow down", "7", retry.RateLimited, 7 * time.Second},
		{"408", 408, "timeout_error", "timeout", "", retry.Timeout, 0},
		{"400", 400, "invalid_request_error", "temperature is not supported on this model", "", retry.ClientError, 0},
		{"401", 401, "authentication_error", "invalid x-api-key", "", retry.ClientError, 0},
	}
	for _, c := range cases {
		api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) {
			if c.retryAfter != "" {
				w.Header().Set("Retry-After", c.retryAfter)
			}
			apiError(w, c.status, c.typ, c.msg)
		})
		_, err := testClient(t, srv.URL, nil).Call(context.Background(), NewConversation(Segment, "x"), nil)
		var ce *CallError
		if !errors.As(err, &ce) {
			t.Errorf("%s: error %v, want *CallError", c.name, err)
			continue
		}
		if ce.Status != c.status || ce.Class != c.class || ce.RetryAfter != c.after {
			t.Errorf("%s: %+v, want status %d class %s retry-after %v", c.name, ce, c.status, c.class, c.after)
		}
		if !strings.Contains(err.Error(), c.msg) {
			t.Errorf("%s: error %q lacks the API message %q", c.name, err, c.msg)
		}
		if api.count() != 1 {
			t.Errorf("%s: %d requests; the SDK retried on its own", c.name, api.count())
		}
	}
}

