// The watchdog cancels a stream with no event for StallTimeout, including
// the wait for the response headers, and any stream older than TotalTimeout.
func TestWatchdog(t *testing.T) {
	release := make(chan struct{})
	t.Cleanup(func() { close(release) })
	wait := func(r *http.Request) {
		select {
		case <-r.Context().Done():
		case <-release:
		}
	}
	cases := []struct {
		name         string
		stall, total time.Duration
		handle       func(w http.ResponseWriter, r *http.Request)
		want         error
		deltas       int
	}{
		{"stall mid-stream", 150 * time.Millisecond, 10 * time.Second, func(w http.ResponseWriter, r *http.Request) {
			streamStart(w, "sig")
			textDelta(w, `{"sms":{"body":"Mer`)
			wait(r)
		}, ErrStalled, 1},
		{"stall before headers", 150 * time.Millisecond, 10 * time.Second, func(_ http.ResponseWriter, r *http.Request) { wait(r) }, ErrStalled, 0},
		{"total timeout with pings", 2 * time.Second, 300 * time.Millisecond, func(w http.ResponseWriter, r *http.Request) {
			streamStart(w, "sig")
			for {
				select {
				case <-r.Context().Done():
					return
				case <-release:
					return
				case <-time.After(20 * time.Millisecond):
					event(w, "ping", `{"type":"ping"}`)
				}
			}
		}, ErrTotalTimeout, 0},
	}
	for _, c := range cases {
		_, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, r *http.Request) { c.handle(w, r) })
		cl := testClient(t, srv.URL, func(cfg *Config) { cfg.StallTimeout, cfg.TotalTimeout = c.stall, c.total })
		var deltas int
		start := time.Now()
		_, err := cl.Call(context.Background(), NewConversation(Content, "x"), func(string) { deltas++ })
		if took := time.Since(start); took > 3*time.Second {
			t.Errorf("%s: took %v; the watchdog did not fire", c.name, took)
		}
		if !errors.Is(err, c.want) {
			t.Errorf("%s: error %v, want %v", c.name, err, c.want)
		}
		var ce *CallError
		if !errors.As(err, &ce) || ce.Class != retry.Timeout {
			t.Errorf("%s: error %v, want a CallError with class timeout so it is retried", c.name, err)
		}
		if deltas != c.deltas {
			t.Errorf("%s: %d deltas before the stall, want %d", c.name, deltas, c.deltas)
		}
	}
	if DefaultStallTimeout != 20*time.Second || DefaultTotalTimeout != 120*time.Second {
		t.Errorf("defaults %v and %v, want 20s and 120s", DefaultStallTimeout, DefaultTotalTimeout)
	}
}

// The repair turn is append-only (preserved thinking on Opus 5.5 forbids
// editing earlier turns): the earlier messages are resent byte for byte, the
// assistant turn goes back unchanged with its thinking block, and the next
// user turn carries the validation errors as JSON.
func TestRepairTurn(t *testing.T) {
	answers := []string{`{"sms":{"body":"Hi {{password}}"}}`, `{"sms":{"body":"Hi {{first_name}}"}}`, `{}`}
	api, srv := newFakeAPI(t, func(n int, w http.ResponseWriter, _ *http.Request) {
		writeStream(w, fmt.Sprintf("sig-%d", n+1), "end_turn", answers[n])
	})
	cl := testClient(t, srv.URL, nil)
	conv := NewConversation(Content, "first turn")
	ctx := context.Background()

	r1, err := cl.Call(ctx, conv, nil)
	if err != nil {
		t.Fatal(err)
	}
	issues1 := []validation.Issue{
		{Path: "/sms/body", Code: validation.UnknownVariable, Message: `variable "password" is not allowed`},
		{Path: "/email", Code: validation.Required, Message: `missing required key "email"`},
	}
	conv.Repair(r1, issues1)
	r2, err := cl.Call(ctx, conv, nil)
	if err != nil {
		t.Fatal(err)
	}
	issues2 := []validation.Issue{{Path: "/email", Code: validation.Required, Message: `missing required key "email"`}}
	conv.Repair(r2, issues2)
	if _, err := cl.Call(ctx, conv, nil); err != nil {
		t.Fatal(err)
	}

	b1, b2, b3 := api.body(0), api.body(1), api.body(2)
	m1, m2, m3 := messages(b1), messages(b2), messages(b3)
	if len(m1) != 1 || len(m2) != 3 || len(m3) != 5 {
		t.Fatalf("message counts %d, %d, %d; want 1, 3, 5", len(m1), len(m2), len(m3))
	}
	if !reflect.DeepEqual(m2[:1], m1) || !reflect.DeepEqual(m3[:3], m2) {
		t.Error("an earlier turn was changed; the conversation must be append-only")
	}
	checkAssistant(t, m2[1], "sig-1", answers[0])
	checkAssistant(t, m3[3], "sig-2", answers[1])
	checkRepairErrors(t, m2[2], issues1)
	checkRepairErrors(t, m3[4], issues2)
	// The cached prefix stays the same across attempts.
	for _, k := range []string{"system", "output_config", "model", "thinking"} {
		if !reflect.DeepEqual(b1[k], b2[k]) || !reflect.DeepEqual(b2[k], b3[k]) {
			t.Errorf("%s changed between attempts", k)
		}
	}
}

func checkAssistant(t *testing.T, m map[string]any, sig, text string) {
	t.Helper()
	if m["role"] != "assistant" {
		t.Fatalf("role %v, want assistant", m["role"])
	}
	var gotSig, gotText []string
	for _, b := range blocks(m) {
		switch b["type"] {
		case "thinking":
			s, _ := b["signature"].(string)
			gotSig = append(gotSig, s)
			if th, _ := b["thinking"].(string); th != "" {
				t.Errorf("thinking text %q, want the empty text that was received", th)
			}
		case "text":
			s, _ := b["text"].(string)
			gotText = append(gotText, s)
		}
	}
	if !slices.Equal(gotSig, []string{sig}) || !slices.Equal(gotText, []string{text}) {
		t.Errorf("assistant turn: thinking signatures %q, texts %q; want [%s] and [%s] unchanged", gotSig, gotText, sig, text)
	}
}

// checkRepairErrors finds the JSON array in the user turn and requires it to
// be exactly the validation issues.
func checkRepairErrors(t *testing.T, m map[string]any, want []validation.Issue) {
	t.Helper()
	if m["role"] != "user" {
		t.Fatalf("role %v, want user", m["role"])
	}
	text := messageText(m)
	i, j := strings.Index(text, "["), strings.LastIndex(text, "]")
	if i < 0 || j < i {
		t.Fatalf("repair turn has no JSON array: %q", text)
	}
	var got []validation.Issue
	if err := json.Unmarshal([]byte(text[i:j+1]), &got); err != nil {
		t.Fatalf("repair turn errors are not JSON: %v: %q", err, text)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("repair turn errors %+v, want %+v", got, want)
	}
}

// ConfigFromEnv fails closed. Mock mode never reads the API key, so a
// misconfigured worker cannot send it to the mock.
func TestConfigFromEnv(t *testing.T) {
	run := func(env map[string]string) (Config, error, []string) {
		var asked []string
		cfg, err := ConfigFromEnv(func(k string) string {
			asked = append(asked, k)
			return env[k]
		})
		return cfg, err, asked
	}
	cfg, err, asked := run(map[string]string{"LLM_MODE": "mock", "ANTHROPIC_API_KEY": "must-not-be-read", "ANTHROPIC_AUTH_TOKEN": "must-not-be-read"})
	if err != nil || cfg.BaseURL != MockBaseURL || cfg.APIKey == "" || cfg.APIKey == "must-not-be-read" || cfg.Model != DefaultModel {
		t.Errorf("mock mode: %+v %v", cfg, err)
	}
	if slices.Contains(asked, "ANTHROPIC_API_KEY") || slices.Contains(asked, "ANTHROPIC_AUTH_TOKEN") {
		t.Errorf("mock mode read the key: asked %v", asked)
	}
	cfg, err, _ = run(map[string]string{"LLM_MODE": "mock", "MOCKLLM_URL": "http://127.0.0.1:8090", "ANTHROPIC_MODEL": "claude-test-model"})
	if err != nil || cfg.BaseURL != "http://127.0.0.1:8090" || cfg.Model != "claude-test-model" {
		t.Errorf("mock mode with overrides: %+v %v", cfg, err)
	}
	if _, err, _ := run(map[string]string{"LLM_MODE": "anthropic"}); !errors.Is(err, ErrNoAPIKey) {
		t.Errorf("anthropic mode without a key: %v, want ErrNoAPIKey", err)
	}
	cfg, err, _ = run(map[string]string{"LLM_MODE": "anthropic", "ANTHROPIC_API_KEY": "placeholder-not-a-real-key"})
	if err != nil || cfg.APIKey != "placeholder-not-a-real-key" || cfg.BaseURL != "" || cfg.Model != DefaultModel {
		t.Errorf("anthropic mode: BaseURL %q, Model %q, key set %v, err %v", cfg.BaseURL, cfg.Model, cfg.APIKey != "", err)
	}
	for _, mode := range []string{"", "Mock", "openai", "real"} {
		if _, err, _ := run(map[string]string{"LLM_MODE": mode, "ANTHROPIC_API_KEY": "placeholder-not-a-real-key"}); !errors.Is(err, ErrUnknownMode) {
			t.Errorf("LLM_MODE=%q: %v, want ErrUnknownMode", mode, err)
		}
	}
}

