		Hub:       NewHub(ctx, p, slog.New(slog.DiscardHandler)),
		Heartbeat: heartbeat,
	}
	srv := httptest.NewUnstartedServer(handler(t, s))
	srv.Config.WriteTimeout = writeTimeout
	srv.Start()
	t.Cleanup(srv.Close)
	return srv, p, s
}

type sseFrame struct {
	ID      int64
	Event   string
	Data    map[string]any
	Comment bool
}

// openStream starts a GET and delivers frames until the server ends the
// stream, which closes the channel.
func openStream(t *testing.T, srv *httptest.Server, path string, header map[string]string) (*http.Response, <-chan sseFrame) {
	t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	req, err := http.NewRequestWithContext(ctx, "GET", srv.URL+path, nil)
	if err != nil {
		t.Fatal(err)
	}
	for k, v := range header {
		req.Header.Set(k, v)
	}
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { resp.Body.Close() })
	frames := make(chan sseFrame, 1024)
	go func() {
		defer close(frames)
		var f sseFrame
		started := false
		sc := bufio.NewScanner(resp.Body)
		sc.Buffer(make([]byte, 1<<20), 1<<20)
		for sc.Scan() {
			line := sc.Text()
			switch {
			case line == "":
				if started {
					frames <- f
				}
				f, started = sseFrame{}, false
			case strings.HasPrefix(line, ":"):
				f.Comment, started = true, true
			case strings.HasPrefix(line, "id: "):
				f.ID, _ = strconv.ParseInt(strings.TrimPrefix(line, "id: "), 10, 64)
				started = true
			case strings.HasPrefix(line, "event: "):
				f.Event, started = strings.TrimPrefix(line, "event: "), true
			case strings.HasPrefix(line, "data: "):
				_ = json.Unmarshal([]byte(strings.TrimPrefix(line, "data: ")), &f.Data)
				started = true
			}
		}
	}()
	return resp, frames
}

// next returns the next event frame, skipping heartbeats.
func next(t *testing.T, frames <-chan sseFrame, within time.Duration) sseFrame {
	t.Helper()
	timeout := time.After(within)
	for {
		select {
		case f, ok := <-frames:
			if !ok {
				t.Fatal("the stream ended early")
			}
			if !f.Comment {
				return f
			}
		case <-timeout:
			t.Fatalf("no event within %v", within)
		}
	}
}

// ended waits for the server to close the stream.
func ended(t *testing.T, frames <-chan sseFrame, within time.Duration) {
	t.Helper()
	timeout := time.After(within)
	for {
		select {
		case f, ok := <-frames:
			if !ok {
				return
			}
			if !f.Comment {
				t.Fatalf("event %+v after the stream should have ended", f)
			}
		case <-timeout:
			t.Fatalf("the stream did not end within %v", within)
		}
	}
}

func newCampaign(t *testing.T, p *pgxpool.Pool) string {
	t.Helper()
	return insertCampaign(t, p, "generating", 1).ID
}

func addEvent(t *testing.T, p *pgxpool.Pool, id, typ string, payload map[string]any) int64 {
	t.Helper()
	n, err := store.InsertGenerationEvent(context.Background(), p, id, typ, payload)
	if err != nil {
		t.Fatal(err)
	}
	return n
}

// The stream sends the stored backlog first, then live events, and ends
// after done.
func TestEventsBacklogThenLive(t *testing.T) {
	srv, p, _ := eventsServer(t, 15*time.Second, 0)
	id := newCampaign(t, p)
	first := addEvent(t, p, id, "segment_ready", map[string]any{"description": "d"})
	second := addEvent(t, p, id, "delta", map[string]any{"field": "sms.body", "text": "Mer"})

	resp, frames := openStream(t, srv, "/api/campaigns/"+id+"/events", bearer)
	if resp.StatusCode != http.StatusOK || !strings.HasPrefix(resp.Header.Get("Content-Type"), "text/event-stream") ||
		!strings.Contains(resp.Header.Get("Cache-Control"), "no-cache") {
		t.Fatalf("status %d, headers %v", resp.StatusCode, resp.Header)
	}
	if f := next(t, frames, 3*time.Second); f.ID != first || f.Event != "segment_ready" || f.Data["description"] != "d" {
		t.Errorf("first frame %+v", f)
	}
	if f := next(t, frames, 3*time.Second); f.ID != second || f.Event != "delta" || f.Data["text"] != "Mer" {
		t.Errorf("second frame %+v", f)
	}
	live := addEvent(t, p, id, "delta", map[string]any{"field": "sms.body", "text": "haba"})
	if f := next(t, frames, 3*time.Second); f.ID != live || f.Data["text"] != "haba" {
		t.Errorf("live frame %+v", f)
	}
	done := addEvent(t, p, id, "done", map[string]any{"revision_id": "r"})
	if f := next(t, frames, 3*time.Second); f.ID != done || f.Event != "done" {
		t.Errorf("done frame %+v", f)
	}
	ended(t, frames, 3*time.Second)
}

func TestEventsEndAfterFailed(t *testing.T) {
